-wrap gap-2"><button type="button" class="button" id="add-price-item">Add item</button><button class="button button-primary">Submit for approval</button></div></form></section>@endcan
<section class="card"><h2>Price list register and approval history</h2><div class="table-wrap"><table><thead><tr><th>Name / items</th><th>Currency</th><th>Effective dates</th><th>Status / review</th><th>Decision</th></tr></thead><tbody>@forelse($priceLists as $list)<tr><td><strong>{{ $list->name }}</strong><small class="block">@foreach($priceItems[$list->id]??[] as $item){{ $item->description }} · {{ number_format((float)$item->unit_price,2) }}@if($item->billing_period) / {{ $item->billing_period }}@endif<br>@endforeach</small></td><td>{{ $list->currency }}</td><td>{{ $list->effective_from }} – {{ $list->effective_until ?: 'No end date' }}</td><td>{{ str_replace('_',' ',ucfirst($list->status)) }}<small class="block">{{ $list->reviewed_at ?: '' }} {{ $list->review_note }}</small></td><td>@if($list->status==='pending_approval' && auth()->user()->can('commercial.prices.approve') && (int)$list->created_by !== (int)auth()->id())<form method="post" action="{{ route('commercial.price-lists.decision',$list->id) }}" class="stack-form">@csrf<select name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option></select><input name="review_note" maxlength="3000" placeholder="Review note"><button class="button">Record decision</button></form>@elseif($list->status==='approved')Ready for quotes when effective @else—@endif</td></tr>@empty<tr><td colspan="5">No price list proposals have been submitted.</td></tr>@endforelse</tbody></table></div><div class="mt-4">{{ $priceLists->links() }}</div></section>
<script>let priceItemIndex={{ count(old('items',[[]])) }};document.getElementById('add-price-item')?.addEventListener('click',()=>{const source=document.querySelector('.price-item');const row=source.cloneNode(true);row.querySelectorAll('input').forEach(e=>e.value='');row.querySelectorAll('select').forEach(e=>e.selectedIndex=0);row.querySelectorAll('[name]').forEach(e=>e.name=e.name.replace(/items\[\d+\]/,`items[${priceItemIndex}]`));document.getElementById('price-items').appendChild(row);priceItemIndex++});document.getElementById('price-items')?.addEventListener('click',e=>{if(e.target.classList.contains('remove-price-item')&&document.querySelectorAll('.price-item').length>1)e.target.closest('.price-item').remove()});</script>
